// The texture slot the patched Lighting/LightDir.hlsl reads (ShaderPatch.cs).
constexpr UINT kOverlaySlot = 22;
// The lamp passes' scale (ShaderPatch.LampShare: x the LampIntensity setting, y 1), bound with the overlay.
constexpr UINT kLampScaleSlot = 23;
static_assert(kLampScaleSlot == kOverlaySlot + 1, "BindLighting binds the two together");
constexpr std::size_t kFramesInFlight = 3;
constexpr std::size_t kTimingSlots = 8;
// SRVs t0-t3; UAVs u0-u8 (output, statistics, the light history written, the
// denoiser's albedo and filter textures); SRVs t9-t12 (the environment
// atlases, the light history read).
constexpr UINT kDescriptorsPerFrame = 25;
// DLSS Ray Reconstruction's textures (u19-u25 in the per-frame table, primary_view.hlsl Rr*, denoise.hlsl).
constexpr std::size_t kRrColor = 0;
constexpr std::size_t kRrDiffuseAlbedo = 1;
constexpr std::size_t kRrSpecularAlbedo = 2;
constexpr std::size_t kRrNormalRoughness = 3;
constexpr std::size_t kRrDepth = 4;
constexpr std::size_t kRrOutput = 5;
constexpr std::size_t kRrSpecularHitDistance = 6;  // u25
constexpr DXGI_FORMAT kRrFormats[7] = {DXGI_FORMAT_R16G16B16A16_FLOAT, DXGI_FORMAT_R16G16B16A16_FLOAT,
                                       DXGI_FORMAT_R16G16B16A16_FLOAT, DXGI_FORMAT_R16G16B16A16_FLOAT,
                                       DXGI_FORMAT_R32_FLOAT,          DXGI_FORMAT_R16G16B16A16_FLOAT,
                                       DXGI_FORMAT_R16_FLOAT};
// After the per-frame descriptors: the scene's geometry pages (scene.h), then
// the material textures (textures.h).
constexpr UINT kPageDescriptorsStart = static_cast<UINT>(kFramesInFlight) * kDescriptorsPerFrame;
constexpr UINT kTextureDescriptorsStart = kPageDescriptorsStart + kMaxGeometryPages;
constexpr UINT64 kConstantsStride = 512;
// Per frame: 112 counters (debug_view.hlsl, primary_view.hlsl; some of them
// emissive_lights.hlsl's), then the probe records of primary_view.hlsl (24
// uints each).
constexpr std::size_t kStatsCounters = 112;
constexpr std::size_t kMaxProbes = 8;
constexpr std::size_t kProbeWords = 24;
constexpr std::uint32_t kNoProbe = 0xFFFFFFFFu;
constexpr UINT64 kProbeOffset = kStatsCounters * 4;
constexpr UINT64 kStatsBytes = kProbeOffset + kMaxProbes * kProbeWords * 4;
static_assert(kStatsBytes == 1216);  // primary_view.hlsl kProbeOffset = 448
constexpr UINT64 kStatsBufferBytes = 4096;  // stats, zeros and readback buffers
constexpr float kFarPlane = 1.0e8f;
constexpr UINT64 kReadbackStatsStride = kStatsBytes;
constexpr UINT64 kReadbackTimestampsOffset = kReadbackStatsStride * kFramesInFlight;
// Per frame: the list's start, the scene mirror's end (texture uploads, mesh and skinned objects' BLASes, the
// TLAS), the light list's end (BuildLights; right after the scene mirror's in the other views), the list's end.
constexpr UINT kTimestampsPerFrame = 4;
constexpr double kReportSeconds = 5.0;
constexpr double kWatchdogSeconds = 2.0;
// How long the gate waits for a slot still in flight before it skips the frame's D3D12 work (WaitForSlot).
constexpr double kSlotWaitMs = 250.0;
constexpr float kGridCellSize = 1.0f;
constexpr UINT kMaxDispatchGroups = 65535;
// Emissive surfaces as lights (emissive_lights.hlsl; the capacities of lights.hlsli): the buffers at
// u9-u15 in register order, their sizes, the dispatch arguments' offset in LightCounters.
constexpr UINT64 kMaxLightMaterials = 1u << 16;  // scene.cpp kMaxMaterials
constexpr UINT64 kMaxLightParts = 65535;         // groups of one ExecuteIndirect dispatch
constexpr UINT64 kMaxLightTriangles = 262144;
constexpr UINT kLightScanBlocks = 256;           // kMaxLightTriangles / kLightScanBlock
constexpr UINT kLightCells = 32 * 32 * 32;
constexpr UINT kLightGridSlots = kLightCells * 16;
constexpr UINT kLightCellEntries = 32;  // per cell, the parts and lamps near it
constexpr UINT kLightWeightBins = 32;   // per cell, its lights counted by weight
constexpr UINT kLightKeySlots = 1u << 19;
constexpr UINT kLightGroupSize = 256;
constexpr std::array<UINT64, 8> kLightBufferBytes = {
    kMaxLightMaterials * 16,  // MaterialLight
    (kMaxLightParts + 1) * 3 * 16,  // LightParts: the parts, their bounds (lights.hlsli kLightPartBounds)
    256,                      // LightCounters
    kMaxLightTriangles * 80,  // Lights
    kMaxLightTriangles * 4 * 2,  // LightCdf: the weights' sums in blocks, the power's in parts (kLightPartCdf)
    kLightScanBlocks * 4,     // LightBlocks
    (static_cast<UINT64>(kLightGridSlots) + kLightCells + static_cast<UINT64>(kLightCells) * kLightCellEntries +
     static_cast<UINT64>(kLightCells) * kLightWeightBins / 2) *
        8,  // LightGrid: the slots, the cells' counters, lists and bins (kLightGridEntries)
    static_cast<UINT64>(kLightKeySlots) * 16,  // LightKeys
};
// The reset pass (one thread per key slot) clears the cells' bins too (emissive_lights.hlsl ResetPass).
static_assert(kLightKeySlots >= kLightCells * kLightWeightBins / 2, "the reset pass covers the cells' bins");
constexpr UINT64 kReservoirBytes = 16;  // LightReservoirs: per pixel and set
constexpr std::size_t kLightCountersBuffer = 2;
constexpr UINT64 kLightArgumentsOffset = 16;  // LightCounters word 4

const wchar_t* ModeName(const int mode) {
    switch (mode) {
    case static_cast<int>(GateMode::off):
        return L"off";
    case static_cast<int>(GateMode::roundTrip):
        return L"round trip";
    case static_cast<int>(GateMode::overlay):
        return L"overlay";
    case static_cast<int>(GateMode::replace):
        return L"replace";
    default:
        return L"unknown";
    }
}

