        // primary_view.hlsl 77-80: lit pixels whose diffuse bounce, specular bounce sampled a light at its hit,
        // unshadowed; 82: whose diffuse bounce brought 40 times the average of its wave's others.
        Info(Format(L"light at the bounces: a light sample at the diffuse bounce's hit on %.1f %% of the lit pixels, "
                    L"unshadowed on %.1f %%; at the specular bounce's hit (glossy surfaces) on %.1f %%, unshadowed "
                    L"on %.1f %%; diffuse bounces 40x above their wave's average on %.3f %%.",
                    100.0 * static_cast<double>(t[77]) / lit, 100.0 * static_cast<double>(t[78]) / lit,
                    100.0 * static_cast<double>(t[79]) / lit, 100.0 * static_cast<double>(t[80]) / lit,
                    100.0 * static_cast<double>(t[82]) / lit));
        // emissive_lights.hlsl 85-89, 94: light-grid cells listing the parts and lamps whose light reaches them,
