        const double cells = frames * kLightCells;
        Info(Format(L"light grid: %.1f %% of the cells list the lights that reach them (%.1f on average of %.1f "
                    L"reaching, %.2f %% of those cells reached by more than %u: the strongest listed); %.1f %% of the "
                    L"slots hold a light, %.1f %% of those drawn from the cell's list.",
                    100.0 * static_cast<double>(t[85]) / cells,
                    t[85] != 0 ? static_cast<double>(t[86]) / static_cast<double>(t[85]) : 0.0,
                    t[85] != 0 ? static_cast<double>(t[94]) / static_cast<double>(t[85]) : 0.0,
                    t[85] != 0 ? 100.0 * static_cast<double>(t[87]) / static_cast<double>(t[85]) : 0.0,
                    kLightCellEntries, 100.0 * static_cast<double>(t[88]) / (cells * 16.0),
                    t[88] != 0 ? 100.0 * static_cast<double>(t[89]) / static_cast<double>(t[88]) : 0.0));
        // emissive_lights.hlsl 95-99, checks of the lists (all 0 while they hold): candidates drawn from a list,
        // those whose light is not the entry drawn; lamp candidates, those whose entry's lamp index (corner.w)
        // is not their place in the list; listing cells whose lights above the threshold's bin are not as many
        // as counted.
        if (t[95] != 0) {
            Info(Format(L"light grid checks: %.0f candidates per frame drawn from the lists, %.4f %% of them not the "
                        L"light drawn; %.4f %% of the lamp candidates naming another lamp; %.4f %% of the listing "
                        L"cells with their strongest lights miscounted.",
                        static_cast<double>(t[95]) / frames,
                        100.0 * static_cast<double>(t[96]) / static_cast<double>(t[95]),
                        t[97] != 0 ? 100.0 * static_cast<double>(t[98]) / static_cast<double>(t[97]) : 0.0,
                        t[85] != 0 ? 100.0 * static_cast<double>(t[99]) / static_cast<double>(t[85]) : 0.0));
        }
        // primary_view.hlsl 90-93: this frame's diffuse light against the history it joins, on pixels with 8
        // frames of it or more: |difference| (x 256), the 8x4 tiles' |summed difference| (x 256), the pixels, the
